// 从 public/dict/dict.json 生成边缘函数词典（按词频取前 12000，紧凑数组格式）
// 用法：npm run gen-dict-edge
import fs from 'node:fs'

const rows = JSON.parse(fs.readFileSync('public/dict/dict.json', 'utf8'))
const sorted = [...rows].sort((a, b) => (b.freq || 0) - (a.freq || 0)).slice(0, 12000)
const compact = sorted.map((d) => [
  d.w,
  d.us || '',
  d.uk || '',
  d.pos || '',
  (d.zh || '').slice(0, 120),
  d.freq || 0,
])

const handler = `/**
 * AUTO-GENERATED by scripts/gen-dict-edge.mjs — do not edit
 * 词典查询：GET /api/dict?q=&limit=&offset=
 */
const DICT = ${JSON.stringify(compact)};

const json = (obj, status = 200) =>
  new Response(JSON.stringify(obj), { status, headers: { 'content-type': 'application/json; charset=utf-8' } })

export async function onRequest({ request }) {
  const u = new URL(request.url)
  const q = (u.searchParams.get('q') || '').trim().toLowerCase()
  const limit = Math.min(Number(u.searchParams.get('limit')) || 30, 100)
  const offset = Math.max(Number(u.searchParams.get('offset')) || 0, 0)
  const hasZh = /[\\u4e00-\\u9fff]/.test(q)

  let matched = []
  if (!q) {
    matched = DICT
  } else {
    for (const it of DICT) {
      const w = it[0].toLowerCase()
      let hit = false
      if (hasZh) hit = it[4].includes(q)
      else if (w === q) hit = true
      else if (w.startsWith(q)) hit = true
      else if (q.length >= 3 && it[4].toLowerCase().includes(q)) hit = true
      if (hit) matched.push(it)
    }
  }

  const toObj = (it) => ({ w: it[0], us: it[1] || undefined, uk: it[2] || undefined, pos: it[3] || undefined, zh: it[4], freq: it[5] })
  const items = matched.slice(offset, offset + limit).map(toObj)
  return json({ total: matched.length, items })
}
`

fs.writeFileSync('edge-functions/api/dict.js', handler)
console.log(`✅ 生成 edge-functions/api/dict.js（${sorted.length} 词条，${(handler.length / 1024 / 1024).toFixed(2)} MB）`)
